package com.rwi.myrepublic.astri.internal;import com.rwi.myrepublic.astri.AstriConfig;import java.io.IOException;import java.net.URI;import java.net.http.HttpClient;import java.net.http.HttpRequest;import java.net.http.HttpResponse;import java.time.Duration;import java.util.Base64;public class WorkOrderUpdateClient{private HttpClient client;private AstriConfig config;private String authHeader;public
WorkOrderUpdateClient(){this.config=AstriConfig.getInstance();this.client=HttpClient.newBuilder().connectTimeout(Duration.ofMillis(config.getConnectionTimeout())).build();String credentials=config.getUsername()+ ":"+config.getPassword();this.authHeader= "Basic "+Base64.getEncoder().encodeToString(credentials.getBytes());}public String updateWorkOrder(String number,String latestStatusName,String detail)throws IOException,InterruptedException{String baseUrl=config.getApiBaseUrl();String path=
"/work-order/update";String url=baseUrl+path;String jsonBody=buildJsonBody(number,latestStatusName,detail);HttpRequest request=HttpRequest.newBuilder().uri(URI.create(url)).header("Authorization",authHeader).header("Content-Type", "application/json").timeout(Duration.ofMillis(config.getRequestTimeout())).PUT(HttpRequest.BodyPublishers.ofString(jsonBody)).build();HttpResponse<String>response=client.send(request,HttpResponse.BodyHandlers.ofString());return response.body();}private String
buildJsonBody(String number,String latestStatusName,String detail){StringBuilder json=new StringBuilder();json.append("{");json.append("\"number\":\"").append(escapeJson(number)).append("\",");json.append("\"latest_status_name\":\"").append(escapeJson(latestStatusName)).append("\",");json.append("\"detail\":\"").append(escapeJson(detail)).append("\"");json.append("}");return json.toString();}private String escapeJson(String str){if(str==null)return "";return str.replace("\\",
"\\\\").replace("\"", "\\\"").replace("\n", "\\n").replace("\r", "\\r").replace("\t", "\\t");}public void close(){}}